---发送奖励导背包，并且通知面板消息
---@param actor any 玩家
---@param rewardsMap table {道具id=数量,道具id=数量}
function Bag.sendRewards(actor, rewardsMap, actionDesc)
    local genericIds = {}
    local tipItems = {}
    local monthCardRewardMap = {}
    local otherRewardMap = {}
    for cfgId, count in pairs(rewardsMap) do
        local itemCfg = ConfigDataManager.getById("cfg_item", cfgId)
        if table.notNullOrEmpty(itemCfg) then
            if table.contains(PrivilegeMonth.getCardCfgIds(), tostring(cfgId)) then
                monthCardRewardMap[cfgId] = count
            end
            otherRewardMap[cfgId] = count
        end
    end

    if not table.isEmpty(monthCardRewardMap) then
        for cfgId, count in pairs(monthCardRewardMap) do
            PrivilegeMonth.usePrivilegeCard(actor, cfgId, count)
            otherRewardMap[cfgId] = nil
        end
    end

    local overlyingItems = {}
    local notOverlyingItems = {}
    -- 添加奖励到背包
    for cfgId, count in pairs(otherRewardMap) do
        local tableValue = ConfigDataManager.getTable("cfg_item", "id", cfgId)
        if table.isNullOrEmpty(tableValue) then
            error("Bag.sendRewards cfgId error", actor:toString(), cfgId)
            goto continue
        end
        local notEnterPack = tableValue[1]["notenterpack"]
        local overlying = tableValue[1]["overlying"]
        local itemType = tonumber(tableValue[1]["type"])
        if (string.isNullOrEmpty(notEnterPack) or tonumber(notEnterPack) == 0) and
                (string.isNullOrEmpty(overlying) or tonumber(overlying) <= 1) and (itemType ~= ItemType.COIN) then
            notOverlyingItems[cfgId] = count
        else
            overlyingItems[cfgId] = count
            -- table.insert(tipItems, { [cfgId] = count })
            tipItems[cfgId] = count
        end
        :: continue ::
    end

    if table.count(overlyingItems) > 0 then
        local ids = additemmaptobag(actor, overlyingItems, 0, 9999, actionDesc)
        for _, id in pairs(ids) do
            table.insert(genericIds, id)
        end
    end

    if table.count(notOverlyingItems) > 0 then
        local ids = additemmaptobag(actor, notOverlyingItems, 0, 9999, actionDesc)
        for _, id in pairs(ids) do
            table.insert(tipItems, { id = id })
            table.insert(genericIds, id)
        end
    end

    if table.count(tipItems) > 0 then
        -- 奖励面板通知
        sendluamsg(actor, LuaMessageIdToClient.COMMON_REWARD_PANEL, tipItems)
    end
    return genericIds
end

---发送奖励导背包，并且通知面板消息
---@param actor any 玩家
---@param rewardsMap table {道具id=数量,道具id=数量}
---@param itemBing string cfg_bind -> bind
function Bag.sendRewardsByBind(actor, rewardsMap, itemBing, actionDesc)
    -- 添加奖励到背包
    additemmaptobag(actor, rewardsMap, itemBing, 9999, actionDesc)
    --奖励面板通知
    sendluamsg(actor, LuaMessageIdToClient.COMMON_REWARD_PANEL, rewardsMap)
end

function Bag.sendRewardsWithoutPanel(actor, rewardsMap, actionDesc, isBind)
    isBind = string.tonumber(isBind)
    -- 添加奖励到背包
    additemmaptobag(actor, rewardsMap, isBind, 9999, actionDesc)
end

-- 背包中道具拆分
function Bag.splitItem(actor, msgData)
    local index = msgData.index
    local count = msgData.count
    local row = msgData.row
    local column = msgData.column
    local cfgId = getcfgidconfigbybagidx(actor, index)
    if cfgId == nil or cfgId == false then
        tipinfo(actor, "道具不存在")
        return
    end
    if row <= 0 or column <= 0 then
        error("参数错误" .. "行号:" .. row .. "列号:" .. column)
        return
    end
    local newIndex = buildbagindex(actor, row, column);
    local moveList = { { srcindex = index, targetindex = newIndex, count = count } }
    if checkbagindex(actor, newIndex, cfgId) then
        moveitem(actor, moveList)
    else
        tipinfo(actor, "当前位置已有道具")
        return
    end
end

MessageRouter:register(LuaMessageIdToSever.REQ_BAG_PROPS_SPLIT, Bag.splitItem)

